import{_ as i,o as t,c as o,a3 as a}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"Entities","description":"","frontmatter":{},"headers":[],"relativePath":"en/projects/fritzbox-to-mqtt/entities.md","filePath":"en/projects/fritzbox-to-mqtt/entities.md","lastUpdated":1793006827000}'),l={name:"en/projects/fritzbox-to-mqtt/entities.md"};function n(s,e,r,d,c,h){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="entities" tabindex="-1">Entities <a class="header-anchor" href="#entities" aria-label="Permalink to &quot;Entities&quot;">​</a></h1><p>Entities are created through MQTT Discovery.</p><h2 id="answering-machines" tabindex="-1">Answering Machines <a class="header-anchor" href="#answering-machines" aria-label="Permalink to &quot;Answering Machines&quot;">​</a></h2><p>For detected answering machines, entities from <code>AB0</code> to <code>AB4</code> are created:</p><ul><li>new messages</li><li>old messages</li><li>status</li><li>on/off switch</li></ul><p>The FRITZ!Box answering machine name is exposed as an attribute and is not used for the entity names.</p><h2 id="wlan" tabindex="-1">WLAN <a class="header-anchor" href="#wlan" aria-label="Permalink to &quot;WLAN&quot;">​</a></h2><p>Depending on the FRITZ!Box, these entities are created:</p><ul><li>WLAN 2.4 GHz on/off</li><li>WLAN 2.4 GHz status</li><li>WLAN 5 GHz on/off</li><li>WLAN 5 GHz status</li><li>guest WLAN on/off</li><li>guest WLAN status</li></ul><p>The WLAN status sensors show <code>Ein</code> or <code>Aus</code>; the raw FRITZ!Box status is kept as an attribute.</p><h2 id="wan-and-box-status" tabindex="-1">WAN And Box Status <a class="header-anchor" href="#wan-and-box-status" aria-label="Permalink to &quot;WAN And Box Status&quot;">​</a></h2><ul><li>connection download</li><li>connection upload</li><li>download rate</li><li>upload rate</li><li>WAN link status</li><li>box mesh role</li><li>box PPP connection</li><li>box PPP IPv4 external</li><li>box IPv6 external</li><li>box DECT</li><li>box DNS over TLS</li></ul><p><code>WAN link status</code> also shows <code>Ein</code> or <code>Aus</code>.</p><p>Optional values that are not exposed by the FRITZ!Box are hidden or published as <code>unknown</code>.</p><h2 id="call-lists-and-live-monitor" tabindex="-1">Call Lists And Live Monitor <a class="header-anchor" href="#call-lists-and-live-monitor" aria-label="Permalink to &quot;Call Lists And Live Monitor&quot;">​</a></h2><p>Configurable call lists:</p><ul><li>all calls</li><li>incoming calls</li><li>outgoing calls</li><li>missed calls</li><li>rejected calls</li><li>blocked calls</li></ul><p>The live call monitor publishes events such as <code>RING</code>, <code>CALL</code>, <code>CONNECT</code> and <code>DISCONNECT</code>.</p><h2 id="phonebooks" tabindex="-1">Phonebooks <a class="header-anchor" href="#phonebooks" aria-label="Permalink to &quot;Phonebooks&quot;">​</a></h2><p>Phonebooks are shown with their detected FRITZ!Box names. Tellows block lists can be hidden through name filters or renamed through <code>phonebook_names</code>.</p><h2 id="dect" tabindex="-1">DECT <a class="header-anchor" href="#dect" aria-label="Permalink to &quot;DECT&quot;">​</a></h2><p>Optionally, each detected DECT handset publishes:</p><ul><li>internal number</li><li>device ID</li></ul><p><code>NoRingTime</code> is intentionally no longer published.</p>',24)])])}const b=i(l,[["render",n]]);export{p as __pageData,b as default};
